namespace ZenForms.Core { [ToolboxBitmap(typeof(ComboBox))][Category("ZenForms Modern Controls")] public class ZenComboBox:UserControl { private readonly ComboBox combo=new ComboBox(); [DesignerSerializationVisibility(DesignerSerializationVisibility.Content)] public ComboBox.ObjectCollection Items{get{return combo.Items;}} public ComboBoxStyle DropDownStyle{get{return combo.DropDownStyle;}set{combo.DropDownStyle=value;}} public int SelectedIndex{get{return combo.SelectedIndex;}set{combo.SelectedIndex=value;}} public override string Text{get{return combo.Text;}set{combo.Text=value;}} public ZenComboBox(){Height=42;MinimumSize=new Size(120,42);BackColor=ZenTheme.Surface;Padding=new Padding(10,7,8,7);combo.Dock=DockStyle.Fill;combo.FlatStyle=FlatStyle.Flat;combo.BackColor=ZenTheme.Surface;combo.ForeColor=ZenTheme.Foreground;combo.Font=ZenTheme.DefaultFont;Controls.Add(combo);SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);} protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(GraphicsPath p=ZenButtonBase.RoundPath(new Rectangle(0,0,Width-1,Height-1),9))using(Pen pen=new Pen(ZenTheme.Border))e.Graphics.DrawPath(pen,p); }/*Watashi wa watashi sore dake*/ } }